export const generateLL1Code = (cfgData, parsingTable, followSets) => {
    const { start_variable, variables, terminals } = cfgData;
    const isTerminal = (sym) => terminals.includes(sym);

    let javascriptCode = `
// ==========================================
// AUTO-GENERATED RECURSIVE DESCENT PARSER
// ==========================================

class Parser {
    constructor(tokens) {
        this.tokens = tokens;
        this.cursor = 0;
        this.errors = []; 
    }

    get lookahead() {
        return this.tokens[this.cursor] || '$';
    }

    match(expected) {
        if (this.lookahead === expected) {
            const token = this.lookahead;
            this.cursor++;
            return { type: 'TERMINAL', value: token };
        }
        
        const errorMsg = \`Parse Error: Expected '\${expected}' but found '\${this.lookahead}' at position \${this.cursor}\`;
        this.errors.push(errorMsg);
        
        return { type: 'ERROR', message: errorMsg, expected, found: this.lookahead };
    }

    parse() {
        const ast = this.parse_${start_variable}();
        if (this.lookahead !== '$') {
            this.errors.push(\`Parse Error: Unexpected trailing tokens starting with '\${this.lookahead}'\`);
        }
        return { ast, errors: this.errors }; 
    }
`;

    for (const nt of variables) {
        javascriptCode += `\n    parse_${nt}() {\n`;
        javascriptCode += `        const node = { type: 'NON_TERMINAL', name: '${nt}', children: [] };\n`;
        javascriptCode += `        switch(this.lookahead) {\n`;

        const row = parsingTable[nt] || {};
        const ruleMap = {};
        for (const [terminal, rule] of Object.entries(row)) {
            const ruleStr = JSON.stringify(rule);
            if (!ruleMap[ruleStr]) ruleMap[ruleStr] = [];
            ruleMap[ruleStr].push(terminal);
        }

        for (const [ruleStr, triggers] of Object.entries(ruleMap)) {
            const rule = JSON.parse(ruleStr);
            triggers.forEach(t => {
                javascriptCode += `            case '${t}':\n`;
            });

            for (const symbol of rule) {
                if (symbol === 'ε') {
                    javascriptCode += `                node.children.push({ type: 'EPSILON', value: 'ε' });\n`;
                } else if (isTerminal(symbol)) {
                    javascriptCode += `                node.children.push(this.match('${symbol}'));\n`;
                } else {
                    javascriptCode += `                node.children.push(this.parse_${symbol}());\n`;
                }
            }
            javascriptCode += `                return node;\n`;
        }

        const syncTokens = followSets[nt] || [];
        javascriptCode += `            default:\n`;
        javascriptCode += `                const errorMsg = \`Parse Error: Unexpected token '\${this.lookahead}' while parsing ${nt}\`;\n`;
        javascriptCode += `                this.errors.push(errorMsg);\n`;
        javascriptCode += `                node.children.push({ type: 'ERROR', message: errorMsg });\n\n`;
        javascriptCode += `                // Panic Mode: Skip tokens until a sync token (FOLLOW set) is found\n`;
        javascriptCode += `                const syncTokens = ${JSON.stringify(syncTokens)};\n`;
        javascriptCode += `                while (this.lookahead !== '$' && !syncTokens.includes(this.lookahead)) {\n`;
        javascriptCode += `                    this.cursor++;\n`;
        javascriptCode += `                }\n`;
        javascriptCode += `                return node;\n`;
        javascriptCode += `        }\n    }\n`;
    }

    javascriptCode += `}\nreturn Parser;\n`;

    const pythonCode = `# Autogenerated LL(1) parser\nimport json\nimport sys\n\nSTART = ${JSON.stringify(start_variable)}\nVARIABLES = ${JSON.stringify(variables)}\nTERMINALS = ${JSON.stringify(terminals)}\nTABLE = ${JSON.stringify(parsingTable, null, 4)}\n\nclass Parser:\n    def tokenize(self, text):\n        result = []\n        cursor = 0\n        terminals = sorted(TERMINALS, key=len, reverse=True)\n        while cursor < len(text):\n            if text[cursor].isspace():\n                cursor += 1\n                continue\n            token = next((item for item in terminals if text.startswith(item, cursor)), None)\n            if token is None:\n                raise ValueError(f"Lexical error at position {cursor}")\n            result.append(token)\n            cursor += len(token)\n        return result + ["$"]\n\n    def parse(self, text):\n        self.tokens = self.tokenize(text)\n        self.cursor = 0\n        tree = self.parse_variable(START)\n        if self.tokens[self.cursor] != "$":\n            raise ValueError(f"Unexpected trailing token {self.tokens[self.cursor]!r}")\n        return tree\n\n    def parse_variable(self, variable):\n        lookahead = self.tokens[self.cursor]\n        rule = TABLE.get(variable, {}).get(lookahead)\n        if rule is None:\n            raise ValueError(f"Unexpected token {lookahead!r} while parsing {variable}")\n        node = {"name": variable, "children": []}\n        for symbol in rule:\n            if symbol == "ε":\n                node["children"].append({"name": "ε", "children": []})\n            elif symbol in TERMINALS:\n                if self.tokens[self.cursor] != symbol:\n                    raise ValueError(f"Expected {symbol!r}, found {self.tokens[self.cursor]!r}")\n                node["children"].append({"name": symbol, "children": []})\n                self.cursor += 1\n            else:\n                node["children"].append(self.parse_variable(symbol))\n        return node\n\nif __name__ == "__main__":\n    if len(sys.argv) != 2:\n        raise SystemExit(f"Usage: python {sys.argv[0]} '<input>'")\n    try:\n        print(json.dumps(Parser().parse(sys.argv[1]), indent=2))\n    except ValueError as error:\n        raise SystemExit(str(error))\n`;

    const cppQuote = (value) => JSON.stringify(String(value));
    const cppRows = Object.entries(parsingTable).map(([variable, row]) => {
        const entries = Object.entries(row).map(([terminal, rule]) => `${cppQuote(terminal)}, {${rule.map(cppQuote).join(', ')}}`);
        return `    {${cppQuote(variable)}, {${entries.map(entry => `{${entry}}`).join(', ')}}}`;
    }).join(',\n');
    const cppTerminals = terminals.map(cppQuote).join(', ');
    const cppCode = `// Autogenerated LL(1) parser\n#include <algorithm>\n#include <cctype>\n#include <iostream>\n#include <stdexcept>\n#include <string>\n#include <unordered_map>\n#include <vector>\n\nstruct Node { std::string name; std::vector<Node> children; };\nusing Row = std::unordered_map<std::string, std::vector<std::string>>;\nconst std::string START = ${cppQuote(start_variable)};\nconst std::vector<std::string> TERMINALS = {${cppTerminals}};\nconst std::unordered_map<std::string, Row> TABLE = {\n${cppRows}\n};\n\nclass Parser {\npublic:\n    std::vector<std::string> tokenize(const std::string& text) const {\n        auto terminals = TERMINALS;\n        std::sort(terminals.begin(), terminals.end(), [](const auto& a, const auto& b) { return a.size() > b.size(); });\n        std::vector<std::string> result;\n        std::size_t cursor = 0;\n        while (cursor < text.size()) {\n            if (std::isspace(static_cast<unsigned char>(text[cursor]))) { ++cursor; continue; }\n            bool matched = false;\n            for (const auto& terminal : terminals) {\n                if (text.compare(cursor, terminal.size(), terminal) == 0) { result.push_back(terminal); cursor += terminal.size(); matched = true; break; }\n            }\n            if (!matched) throw std::runtime_error("Lexical error at position " + std::to_string(cursor));\n        }\n        result.push_back("$");\n        return result;\n    }\n\n    Node parse(const std::string& text) {\n        tokens = tokenize(text);\n        cursor = 0;\n        Node root = parseVariable(START);\n        if (tokens.at(cursor) != "$") throw std::runtime_error("Unexpected trailing input");\n        return root;\n    }\nprivate:\n    std::vector<std::string> tokens;\n    std::size_t cursor = 0;\n    Node parseVariable(const std::string& variable) {\n        const auto row = TABLE.find(variable);\n        if (row == TABLE.end()) throw std::runtime_error("Missing table row for " + variable);\n        const auto production = row->second.find(tokens.at(cursor));\n        if (production == row->second.end()) throw std::runtime_error("Unexpected token '" + tokens.at(cursor) + "' while parsing " + variable);\n        Node node{variable, {}};\n        for (const auto& symbol : production->second) {\n            if (symbol == "ε") node.children.push_back(Node{"ε", {}});\n            else if (std::find(TERMINALS.begin(), TERMINALS.end(), symbol) != TERMINALS.end()) {\n                if (tokens.at(cursor) != symbol) throw std::runtime_error("Expected '" + symbol + "'");\n                node.children.push_back(Node{symbol, {}});\n                ++cursor;\n            } else node.children.push_back(parseVariable(symbol));\n        }\n        return node;\n    }\n};\n\nint main(int argc, char** argv) {\n    if (argc != 2) { std::cerr << "Usage: parser '<input>'\\n"; return 2; }\n    try { Parser parser; std::cout << "Accepted: " << parser.parse(argv[1]).name << "\\n"; }\n    catch (const std::exception& error) { std::cerr << error.what() << "\\n"; return 1; }\n}\n`;

    return { javascript: javascriptCode, python: pythonCode, cpp: cppCode };
};